package com.ruoyi.projectmanagement.task.service.impl;
import com.ruoyi.projectmanagement.deliverable.mapper.ProjectDeliverableMapper;
import com.ruoyi.common.exception.ServiceException;import com.ruoyi.common.utils.StringUtils;import com.ruoyi.projectmanagement.common.enums.*;import com.ruoyi.projectmanagement.execution.domain.LifecycleActionRequest;import com.ruoyi.projectmanagement.project.domain.ProjectInfo;import com.ruoyi.projectmanagement.project.mapper.ProjectInfoMapper;import com.ruoyi.projectmanagement.task.domain.*;import com.ruoyi.projectmanagement.task.mapper.ProjectTaskMapper;import com.ruoyi.projectmanagement.task.service.IProjectTaskService;import com.ruoyi.projectmanagement.team.service.IProjectTeamService;import com.ruoyi.projectmanagement.wbs.domain.ProjectWbsNode;import com.ruoyi.projectmanagement.wbs.mapper.ProjectWbsMapper;import com.ruoyi.projectmanagement.wbs.service.IProjectWbsService;import java.time.LocalDate;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ProjectTaskServiceImpl implements IProjectTaskService {private final ProjectTaskMapper mapper;private final ProjectWbsMapper wbsMapper;private final ProjectInfoMapper projectMapper;private final IProjectTeamService teamService;private final IProjectWbsService wbsService;private final ProjectDeliverableMapper deliverableMapper;public ProjectTaskServiceImpl(ProjectTaskMapper m,ProjectWbsMapper w,ProjectInfoMapper p,IProjectTeamService team,IProjectWbsService ws,ProjectDeliverableMapper dm){mapper=m;wbsMapper=w;projectMapper=p;teamService=team;wbsService=ws;deliverableMapper=dm;}public List<ProjectTask> list(ProjectTask f){return mapper.selectList(f);}public ProjectTask get(Long id){return required(id);}
@Transactional public int add(ProjectTask t,String op){assertStructureMutable(t.getProjectId());normalize(t);ProjectWbsNode wp=workPackage(t.getWorkPackageId(),t.getProjectId());validate(t,wp);t.setTaskCode(nextCode(wp,t.getParentTaskId()));t.setStatus(WorkItemStatus.NOT_STARTED.getCode());t.setProgress(0);t.setCreateBy(op);int rows=mapper.insert(t);refreshPackage(t.getWorkPackageId());return rows;}
@Transactional public int edit(ProjectTask t,String op){ProjectTask old=required(t.getTaskId());assertStructureMutable(old.getProjectId());t.setProjectId(old.getProjectId());t.setWorkPackageId(old.getWorkPackageId());t.setParentTaskId(old.getParentTaskId());t.setTaskType(old.getTaskType());t.setUpdateBy(op);validate(t,workPackage(old.getWorkPackageId(),old.getProjectId()));int rows=mapper.update(t);refreshPackage(old.getWorkPackageId());return rows;}
@Transactional public int remove(Long id,String op){ProjectTask t=required(id);assertStructureMutable(t.getProjectId());if(mapper.countChildren(id)>0)throw new ServiceException("汇总任务仍有下级，不能删除");if(!mapper.selectOutputs(id).isEmpty())throw new ServiceException("任务已有成果，不能删除");int rows=mapper.delete(id);refreshPackage(t.getWorkPackageId());return rows;}
@Transactional public int lifecycle(Long id,LifecycleActionRequest r,String op){ProjectTask t=required(id);if(!TaskType.EXECUTION.matches(t.getTaskType()))throw new ServiceException("汇总任务由下级自动汇总，不能执行生命周期动作");if(!"admin".equalsIgnoreCase(op)&&(StringUtils.isBlank(t.getAssigneeCode())||!t.getAssigneeCode().equalsIgnoreCase(op)))throw new ServiceException("只有任务执行人或admin可以执行该操作");ProjectInfo p=projectMapper.selectProjectInfoById(t.getProjectId());if(p==null||!ProjectStatus.ACTIVE.matches(p.getStatus()))throw new ServiceException("项目未执行中，不能执行任务动作");String a=r.getAction().trim().toUpperCase(),from=t.getStatus(),to;switch(a){case "START"->{if(!WorkItemStatus.NOT_STARTED.matches(from))throw new ServiceException("只有未开始任务可以开始");to=WorkItemStatus.ACTIVE.getCode();t.setActualStartDate(LocalDate.now());}case "PAUSE"->{if(!WorkItemStatus.ACTIVE.matches(from)||StringUtils.isBlank(r.getReason()))throw new ServiceException("只有进行中任务可以暂停，且必须填写原因");to=WorkItemStatus.PAUSED.getCode();t.setPauseReason(r.getReason());}case "RESUME"->{if(!WorkItemStatus.PAUSED.matches(from))throw new ServiceException("只有已暂停任务可以恢复");to=WorkItemStatus.ACTIVE.getCode();t.setPauseReason(null);}case "COMPLETE"->{if(!WorkItemStatus.ACTIVE.matches(from))throw new ServiceException("只有进行中任务可以完成");to=WorkItemStatus.COMPLETED.getCode();t.setActualEndDate(LocalDate.now());t.setProgress(100);}default->throw new ServiceException("不支持的任务动作");}t.setStatus(to);t.setUpdateBy(op);int rows=mapper.updateLifecycle(t);refreshPackage(t.getWorkPackageId());return rows;}
public List<ProjectTaskOutput> outputs(Long id){required(id);return mapper.selectOutputs(id);}@Transactional public int addOutput(ProjectTaskOutput o,String op){ProjectTask t=required(o.getTaskId());if(!TaskType.EXECUTION.matches(t.getTaskType()))throw new ServiceException("只有执行任务可以上传任务成果");assertTaskOwner(t,op);if(WorkItemStatus.COMPLETED.matches(t.getStatus()))throw new ServiceException("已完成任务的成果仅可查看");o.setCreateBy(op);return mapper.insertOutput(o);}@Transactional public int removeOutput(Long id,String op){ProjectTaskOutput o=mapper.selectOutput(id);if(o==null)throw new ServiceException("任务成果不存在");ProjectTask t=required(o.getTaskId());assertTaskOwner(t,op);if(WorkItemStatus.COMPLETED.matches(t.getStatus()))throw new ServiceException("已完成任务的成果仅可查看");return mapper.deleteOutput(id);}
@Transactional public void refreshPackage(Long packageId){ProjectWbsNode wp=wbsMapper.selectById(packageId);if(wp==null)return;ProjectTask f=new ProjectTask();f.setWorkPackageId(packageId);List<ProjectTask> all=mapper.selectList(f);all.stream().sorted(Comparator.comparingInt(x->-depth(x,all))).filter(x->TaskType.SUMMARY.matches(x.getTaskType())).forEach(x->{List<ProjectTask> c=all.stream().filter(y->x.getTaskId().equals(y.getParentTaskId())).toList();int progress=c.isEmpty()?0:(int)Math.round(c.stream().mapToInt(y->y.getProgress()==null?0:y.getProgress()).average().orElse(0));String status=progress==100?WorkItemStatus.COMPLETED.getCode():c.stream().anyMatch(y->!WorkItemStatus.NOT_STARTED.matches(y.getStatus()))?WorkItemStatus.ACTIVE.getCode():WorkItemStatus.NOT_STARTED.getCode();mapper.updateAggregate(x.getTaskId(),status,progress);x.setStatus(status);x.setProgress(progress);});List<ProjectTask> roots=all.stream().filter(x->x.getParentTaskId()==0).toList();int progress=roots.isEmpty()?0:(int)Math.round(roots.stream().mapToInt(x->x.getProgress()==null?0:x.getProgress()).average().orElse(0));boolean tasksDone=!roots.isEmpty()&&roots.stream().allMatch(x->WorkItemStatus.COMPLETED.matches(x.getStatus()));boolean delivered=tasksDone&&deliverableMapper.countUnsatisfiedRequiredByWorkPackageId(packageId)==0;String status=delivered?WbsStatus.COMPLETED.name():tasksDone?WbsStatus.WAITING_DELIVERY.name():progress>0?WbsStatus.ACTIVE.name():WbsStatus.NOT_STARTED.name();if(delivered)progress=100;else if(tasksDone)progress=99;wbsMapper.updateAggregate(packageId,wp.getPlanStartDate(),wp.getPlanEndDate(),status,progress);wbsService.refreshProject(wp.getProjectId());}
private void validate(ProjectTask t,ProjectWbsNode wp){if(t.getParentTaskId()!=0){ProjectTask p=required(t.getParentTaskId());if(!wp.getWbsId().equals(p.getWorkPackageId()))throw new ServiceException("上级任务不属于当前工作包");if(TaskType.EXECUTION.matches(p.getTaskType()))throw new ServiceException("执行任务不能包含子任务");}if(TaskType.EXECUTION.matches(t.getTaskType())){if(t.getAssigneeId()==null||!teamService.isActiveMember(t.getProjectId(),t.getAssigneeId()))throw new ServiceException("任务执行人必须是当前项目在组成员");if(t.getPlanStartDate()==null||t.getPlanEndDate()==null)throw new ServiceException("请填写执行任务计划日期");if(t.getPlanEndDate().isBefore(t.getPlanStartDate()))throw new ServiceException("任务结束日期不能早于开始日期");if(t.getPlanStartDate().isBefore(wp.getPlanStartDate())||t.getPlanEndDate().isAfter(wp.getPlanEndDate()))throw new ServiceException("任务计划日期必须在工作包周期内（"+wp.getPlanStartDate()+" ~ "+wp.getPlanEndDate()+"）");if(t.getParentTaskId()!=0){ProjectTask p=required(t.getParentTaskId());if(p.getPlanStartDate()!=null&&(t.getPlanStartDate().isBefore(p.getPlanStartDate())||t.getPlanEndDate().isAfter(p.getPlanEndDate())))throw new ServiceException("子任务计划日期必须在上级任务周期内（"+p.getPlanStartDate()+" ~ "+p.getPlanEndDate()+"）");}}}
private ProjectWbsNode workPackage(Long id,Long projectId){ProjectWbsNode w=wbsMapper.selectById(id);if(w==null||!projectId.equals(w.getProjectId())||!WbsNodeType.WORK_PACKAGE.matches(w.getNodeType()))throw new ServiceException("所属工作包不存在");return w;}private String nextCode(ProjectWbsNode wp,Long parentId){List<ProjectTask> c=mapper.selectChildren(wp.getWbsId(),parentId);String prefix=parentId==0?wp.getWbsCode()+"-T":required(parentId).getTaskCode()+".";return prefix+(c.size()+1);}private void normalize(ProjectTask t){if(t.getParentTaskId()==null)t.setParentTaskId(0L);if(t.getSortOrder()==null)t.setSortOrder(0);}private int depth(ProjectTask t,List<ProjectTask> all){int d=0;Long p=t.getParentTaskId();while(p!=null&&p!=0){d++;Long id=p;p=all.stream().filter(x->x.getTaskId().equals(id)).map(ProjectTask::getParentTaskId).findFirst().orElse(0L);}return d;}private ProjectTask required(Long id){ProjectTask t=mapper.selectById(id);if(t==null)throw new ServiceException("任务不存在");return t;}private void assertTaskOwner(ProjectTask t,String op){if(!"admin".equalsIgnoreCase(op)&&(StringUtils.isBlank(t.getAssigneeCode())||!t.getAssigneeCode().equalsIgnoreCase(op)))throw new ServiceException("只有任务执行人或admin可以维护任务成果");}private void assertStructureMutable(Long id){ProjectInfo p=projectMapper.selectProjectInfoById(id);if(p==null||!ProjectStatus.APPROVED.matches(p.getStatus()))throw new ServiceException("只有已立项待启动项目可以调整任务结构");}}
